+// SPDX-License-Identifier: MPL-2.0
+
+//! QEMU pvpanic PCI device support.
+//!
+//! The component claims the pvpanic PCI function and exposes its capability and enabled event
+//! masks through `/sys/pvpanic/{capability,events}`.
+
+#![no_std]
+#![deny(unsafe_code)]
+
+extern crate alloc;
+
+use alloc::{format, sync::Arc};
+
+use aster_pci::{
+    PciDeviceId, PCI_BUS,
+    bus::{PciDevice, PciDriver},
+    cfg_space::{Bar, BarAccess},
+    common_device::PciCommonDevice,
+};
+use aster_systree::{
+    Error as SysTreeError, NormalNodeFields, Result as SysTreeResult, SysAttrSetBuilder, SysPerms,
+    SysStr, inherit_sys_leaf_node, primary_tree,
+};
+use component::{ComponentInitError, init_component};
+use ostd::{
+    bus::BusProbeError,
+    mm::{FallibleVmRead, FallibleVmWrite, VmReader, VmWriter},
+    sync::SpinLock,
+};
+use spin::Once;
+
+macro_rules! __log_prefix {
+    () => {
+        "pvpanic: "
+    };
+}
+
+const PVPANIC_VENDOR_ID: u16 = 0x1b36;
+const PVPANIC_DEVICE_ID: u16 = 0x0011;
+const PVPANIC_BAR_MIN_SIZE: u64 = 1;
+const PVPANIC_EVENTS_MASK: u8 = 0x07;
+
+static PVPANIC_STATE: Once<Arc<SpinLock<PvPanicState>>> = Once::new();
+
+#[init_component]
+fn init() -> Result<(), ComponentInitError> {
+    PCI_BUS
+        .lock()
+        .register_driver(Arc::new(PvPanicPciDriver));
+    Ok(())
+}
+
+#[derive(Debug)]
+struct PvPanicState {
+    bar: BarAccess,
+    capability: u8,
+    events: u8,
+}
+
+#[derive(Debug)]
+struct PvPanicPciDevice {
+    device_id: PciDeviceId,
+    _common_device: PciCommonDevice,
+}
+
+impl PciDevice for PvPanicPciDevice {
+    fn device_id(&self) -> PciDeviceId {
+        self.device_id
+    }
+}
+
+#[derive(Debug)]
+struct PvPanicPciDriver;
+
+impl PciDriver for PvPanicPciDriver {
+    fn probe(
+        &self,
+        mut device: PciCommonDevice,
+    ) -> Result<Arc<dyn PciDevice>, (BusProbeError, PciCommonDevice)> {
+        let device_id = *device.device_id();
+        if device_id.vendor_id != PVPANIC_VENDOR_ID || device_id.device_id != PVPANIC_DEVICE_ID {
+            return Err((BusProbeError::DeviceNotMatch, device));
+        }
+
+        if PVPANIC_STATE.get().is_some() {
+            ostd::error!("only one pvpanic PCI device is supported");
+            return Err((BusProbeError::ConfigurationSpaceError, device));
+        }
+
+        let Some(bar) = acquire_bar0(&mut device) else {
+            ostd::error!("BAR0 is missing, not MMIO, too small, or cannot be mapped");
+            return Err((BusProbeError::ConfigurationSpaceError, device));
+        };
+        let capability = match bar.read_once::<u8>(0) {
+            Ok(value) => mask_capability(value),
+            Err(_) => {
+                ostd::error!("failed to read the capability byte from BAR0");
+                return Err((BusProbeError::ConfigurationSpaceError, device));
+            }
+        };
+
+        let state = Arc::new(SpinLock::new(PvPanicState {
+            bar,
+            capability,
+            events: capability,
+        }));
+        let control_node = PvPanicControlNode::new(state.clone());
+        if primary_tree().root().add_child(control_node).is_err() {
+            ostd::error!("failed to publish /sys/pvpanic controls");
+            return Err((BusProbeError::ConfigurationSpaceError, device));
+        }
+        PVPANIC_STATE.call_once(|| state);
+
+        ostd::info!(
+            "initialized PCI device {:04x}:{:04x} with capability {:02x}",
+            device_id.vendor_id,
+            device_id.device_id,
+            capability
+        );
+        Ok(Arc::new(PvPanicPciDevice {
+            device_id,
+            _common_device: device,
+        }))
+    }
+}
+
+fn acquire_bar0(device: &mut PciCommonDevice) -> Option<BarAccess> {
+    let bar0 = device.bar_manager_mut().bar_mut(0)?;
+    match bar0 {
+        Bar::Memory(memory_bar) if memory_bar.size() >= PVPANIC_BAR_MIN_SIZE => bar0.acquire().ok(),
+        Bar::Memory(_) | Bar::Io(_) => None,
+    }
+}
+
+const fn mask_capability(value: u8) -> u8 {
+    value & PVPANIC_EVENTS_MASK
